package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Saves the split claim and adds the new OPEN claim with the split-off amount, the same date and note, the next
 *  number, opened by the user, its due-by fixed now from the terms in force on the sheet's today, split from the claim, carrying its tags, and a
 *  late entry when the claim is one. */
public class SaveSplit {
    public void save(@Val ValidSplit request, @Val Claim claim, Claims claims, People people, Settings settings,
            ClaimNumbering numbering, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays, Out<ClaimSplit> split) {
        claims.save(claim);
        claims.bind(claim);
        String sheetId = claim.getSheetId();
        Person person = people.find(sheetId, claim.getPersonId());
        Claim into = claims.add(sheetId, person.getId(), request.amount(), claim.getDate(), claim.getNote(),
                holidays.dueBy(sheetId, claim.getDate(), settings.termsOnCreation(sheetId, person)));
        into.setStatus(ClaimStatus.OPEN);
        into.setNumber(numbering.next(sheetId, into.getPeriodDate()));
        into.setOpenedBy(request.user());
        into.setSplitFrom(claim.getNumber());
        into.setTags(claim.getTags());
        claims.save(into);
        claims.splitFrom(into);
        if (claim.isLateEntry()) {
            // A split is judged by the original claim alone: the new claim is a late entry as it is.
            claims.markLateEntry(into);
        }
        log.record(into, person, request.user());
        split.set(new ClaimSplit(into));
    }
}
package net.officefloor.hq.app.claim;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Opens the selected claims in list order (people in the order they were added, newest claim first
 * within a person), numbering each as it opens and auditing it as a single open would be. A selected
 * claim that cannot be opened (not DRAFT, its due-by inside a closed period, the user's role may not open, its note is empty while its due is above the note threshold, its person is flagged and the user is not a steward, or its person already has as many OPEN or PENDING claims in its period as the period's cap) is left as it is and counted
 * as refused; so is a selected id that is not a claim on the sheet. A claim whose due is above the review threshold goes to
 * REVIEW instead and counts as opened.
 */
public class BulkOpenClaims {
    public void open(@PathVariable("sheetId") String sheetId, @RequestBody BulkOpenRequest request,
            Claims claims, People people, Periods periods, Settings settings, Sheets sheets, Rates rates, ClaimNumbering numbering, Rollup rollup, Audit audit, ClaimLog log,
            ObjectResponse<BulkOpenResponse> response) {
        Set<String> selected = new HashSet<>(request.claimIds() == null ? List.of() : request.claimIds());
        List<Claim> all = claims.list(sheetId);
        // A role the sheet's open permission does not allow opens none of them.
        boolean allowed = settings.allows(sheetId, request.user(), "open");
        boolean steward = Settings.STEWARD.equals(settings.role(sheetId, request.user()));
        int opened = 0;
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !selected.contains(String.valueOf(claim.getId()))) {
                    continue;
                }
                if (!allowed || !claim.getStatus().canBecome(ClaimStatus.OPEN)
                        || periods.isClosed(sheetId, claim.getPeriodDate())) {
                    continue;
                }
                java.math.RoundingMode rounding = Rounding.of(claim, settings.policyDate(sheetId), on -> settings.roundingMode(sheetId, on));
                try {
                    ApplyClaimStatus.refuseFlagged(claim, sheets, people, steward);
                    ApplyClaimStatus.refuseNoteless(claim, sheets, people, rates, settings, rounding);
                    ApplyClaimStatus.refuseOverCap(claim, periods, all);
                } catch (ClaimStatusRefusedException e) {
                    continue;
                }
                if (ApplyClaimStatus.needsReview(claim, sheets, people, rates, settings, rounding)) {
                    // Above the review threshold it goes to REVIEW, unnumbered, and counts as opened.
                    claim.setOpenedBy(request.user());
                    claim.setStatus(ClaimStatus.REVIEW);
                    claims.save(claim);
                    log.record(claim, person, request.user());
                    audit.recordOnCommit(ClaimAudit.line("CLAIM_REVIEW", request.user(), person, claim, null));
                    opened++;
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                claim.setNumber(numbering.next(sheetId, claim.getPeriodDate()));
                claim.setOpenedBy(request.user());
                claim.setStatus(ClaimStatus.OPEN);
                claims.save(claim);
                log.record(claim, person, request.user());
                audit.recordOnCommit(ClaimAudit.line("CLAIM_OPENED", request.user(), person, claim, claim.getNumber()));
                rollup.recordChanges(sheetId, request.user(), before);
                opened++;
            }
        }
        response.send(new BulkOpenResponse(opened, selected.size() - opened));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Settles the selected claims in list order (people in the order they were added, newest claim first
 * within a person), each by exactly the rules of settling one claim and audited as a single settle
 * would be. A claim that goes to PENDING counts as settled. It is all-or-nothing: when any selected claim cannot be
 * settled (or a selected id is not a claim on the sheet), none is settled, every one counts as refused and nothing is
 * written. A bulk settle that settles at least one claim is the sheet's next batch, and each claim it settled keeps
 * that batch's number; after the claims' own lines it audits BATCH_SETTLED with the batch's count and the total of
 * the frozen figures of those SETTLED.
 */
public class BulkSettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @RequestBody BulkSettleRequest request,
            Claims claims, Sheets sheets, People people, Rates rates, Periods periods, Settings settings,
            ClaimNumbering numbering, Rollup rollup, Audit audit, ClaimLog log, Watches watches,
            ObjectResponse<BulkSettleResponse> response) {
        Set<String> selected = new HashSet<>(request.claimIds() == null ? List.of() : request.claimIds());
        ValidClaimStatus settle = new ValidClaimStatus(ClaimStatus.SETTLED, request.user(),
                ValidClaimStatus.Decision.NONE, null);
        List<Claim> all = claims.list(sheetId);
        // First every selected claim is judged by the rules of a single settle; a refusal of any refuses them all.
        List<Claim> changed = new ArrayList<>();
        List<ClaimNumber> numbers = new ArrayList<>();
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !selected.contains(String.valueOf(claim.getId()))) {
                    continue;
                }
                try {
                    numbers.add(ApplyClaimStatus.change(settle, claim, sheets, people, rates, periods, settings, numbering, log));
                } catch (ClaimStatusRefusedException refused) {
                    response.send(new BulkSettleResponse(0, selected.size()));
                    return;
                }
                changed.add(claim);
            }
        }
        if (changed.size() != selected.size()) {
            // A selected id that is not a claim on the sheet is refused, so the whole bulk settle is.
            response.send(new BulkSettleResponse(0, selected.size()));
            return;
        }
        List<Claim> settled = new ArrayList<>();
        for (int i = 0; i < changed.size(); i++) {
            Claim claim = changed.get(i);
            RollupFigures before = rollup.figures(sheetId);
            claims.save(claim);
            AuditClaimStatus.record(settle, claim, numbers.get(i), people, audit, before, rollup, log, watches);
            settled.add(claim);
        }
        if (!settled.isEmpty()) {
            int batch = sheets.nextSettleBatch(sheetId);
            BigDecimal total = new BigDecimal("0.00");
            for (Claim claim : settled) {
                claim.setSettleBatch(batch);
                claims.settleBatch(claim);
                if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
                    total = total.add(claim.getSettledDue());
                }
            }
            audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + request.user() + " batch=" + batch
                    + " count=" + settled.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
        }
        response.send(new BulkSettleResponse(settled.size(), selected.size() - settled.size()));
    }
}
        List<Claim> ordered = new ArrayList<>();
        for (Person person : listed) {
            for (Claim claim : all) {
                if (claim.getPersonId() == person.getId() && selected.contains(String.valueOf(claim.getId()))) {
                    ordered.add(claim);
                }
            }
        }
        int reassigned = 0;
        if (to != null && settings.allows(sheetId, request.user(), "reassign")) {
            for (Claim claim : ordered) {
                ClaimStatus status = claim.getStatus();
                if (status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING) {
                    continue;
                }
                if (periods.isClosed(sheetId, claim.getPeriodDate()) || !to.allowsClaimOn(claim.getDate())) {
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                Person from = people.find(sheetId, claim.getPersonId());
                claim.setPersonId(to.getId());
                claim.setStated(false);
                claim.setStatedDue(null);
                if (claim.getNumber() != null) {
                    claim.setNumber(numbering.next(sheetId, claim.getPeriodDate()));
                }
                claims.reassign(claim);
                audit.recordOnCommit(ClaimAudit.line("CLAIM_REASSIGNED", request.user(), to, claim, claim.getNumber())
                        + " from=" + from.getName() + " to=" + to.getName());
                rollup.recordChanges(sheetId, request.user(), before);
                reassigned++;
            }
        }
        response.send(new BulkReassignResponse(reassigned, selected.size() - reassigned));
    }
}
