package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * A steward re-dates an OPEN or PENDING claim; not to a date after its person's retirement, nor a claim whose
 * due-by is inside a closed period. Its due-by stays as it was fixed and a figure a statement bound it to stays
 * bound; as its period goes by its due-by, it keeps its period and its number.
 */
public class ApplyRedate {
    public void apply(@Val ValidRedate request, @Val Claim claim, Settings settings, People people, Periods periods,
            Out<ClaimRedate> redate) throws ClaimStatusRefusedException {
        refuse(claim, request, settings, people, periods);
        redate.set(new ClaimRedate(claim.getDate()));
        // The claim's period goes by its due-by, which a re-dating leaves as it is: it keeps its period and number.
        claim.setDate(request.date());
    }

    /** Refuses a re-dating these rules do not allow; a bulk re-date applies the same rules to each claim. */
    static void refuse(Claim claim, ValidRedate request, Settings settings, People people, Periods periods)
            throws ClaimStatusRefusedException {
        String sheetId = claim.getSheetId();
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new ClaimStatusRefusedException("Only a steward can re-date a claim");
        }
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusRefusedException("Only an OPEN or PENDING claim can be re-dated");
        }
        Person person = people.find(sheetId, claim.getPersonId());
        if (person != null && !person.allowsClaimOn(request.date())) {
            throw new ClaimStatusRefusedException("No claim can be dated after the person's retirement date");
        }
        if (periods.isClosed(sheetId, claim.getPeriodDate())) {
            throw new ClaimStatusRefusedException("No claim whose due-by is inside a closed period can be re-dated");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.RoundingMode;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/**
 * Part-settles an OPEN claim: the settle's four-eyes and proof rules are judged on the original claim, as it is
 * before the split, and the user's role must be one that may settle; then the amount is split off as the split
 * button does. The new claim is settled by {@link SettleSplitOff}.
 */
public class ApplySettlePart {
    public void apply(@Val ValidSplit request, @Val Claim claim, Sheets sheets, People people, Rates rates,
            Periods periods, Settings settings) throws ClaimStatusRefusedException {
        if (!settings.allows(claim.getSheetId(), request.user(), "settle")) {
            throw new ClaimStatusRefusedException("Your role may not settle a claim on this sheet");
        }
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()),
                on -> settings.roundingMode(claim.getSheetId(), on));
        ApplyClaimStatus.refuseSettleRules(claim, request.user(), sheets, people, rates, settings, rounding);
        new ApplySplit().apply(request, claim, sheets, periods, settings);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Watches;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/**
 * Settles the claim a part-settle split off, by the user, as the settle button does (PENDING above the clerk limit),
 * its four-eyes and proof rules having been judged on the original claim. A refusal rolls back the whole part-settle.
 */
public class SettleSplitOff {
    public void settle(@Val ValidSplit request, @Val ClaimSplit split, Claims claims, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, ClaimLog log, Audit audit,
            Rollup rollup, Watches watches) throws ClaimStatusRefusedException {
        Claim into = split.into();
        RollupFigures before = rollup.figures(into.getSheetId());
        ValidClaimStatus settle = new ValidClaimStatus(ClaimStatus.SETTLED, request.user(),
                ValidClaimStatus.Decision.NONE, null);
        ClaimNumber number = ApplyClaimStatus.change(settle, into, sheets, people, rates, periods, settings, numbering,
                log, false);
        claims.save(into);
        AuditClaimStatus.record(settle, into, number, people, audit, before, rollup, log, watches);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Re-settles a SETTLED claim; only a steward re-settles, and not a claim whose due-by is inside a closed period.
 * The settled due is frozen again at the figure the claim would have today as an open claim bound by no
 * statement: its amount at the rate of its person's grade in force on its date, with its late charge as of
 * today (worked on the floored figure) on top, the figure first raised to the floor in force on its date.
 */
public class ApplyResettle {
    public void apply(@Val ResettleRequest request, @Val Claim claim, Sheets sheets, People people, Rates rates,
            Periods periods, Settings settings, Out<ClaimResettle> resettle) throws ClaimStatusRefusedException {
        String sheetId = claim.getSheetId();
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new ClaimStatusRefusedException("Only a steward can re-settle a claim");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusRefusedException("Only a SETTLED claim can be re-settled");
        }
        if (periods.isClosed(sheetId, claim.getPeriodDate())) {
            throw new ClaimStatusRefusedException("No claim whose due-by is inside a closed period can be re-settled");
        }
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(sheetId), on -> settings.roundingMode(sheetId, on));
        String grade = people.find(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
        BigDecimal figure = Rates.due(claim.getAmount(), rates.find(claim, grade), rounding);
        BigDecimal base = LateCharge.floored(claim, figure, settings.floor(sheetId, claim.getDate()));
        BigDecimal due = base == null ? null
                : base.add(LateCharge.asOpen(claim, base, on -> settings.latePct(sheetId, on),
                        sheets.today(sheetId), rounding, settings.grace(sheetId, grade, claim.getDate())));
        BigDecimal old = claim.getSettledDue();
        claim.setSettledDue(due);
        resettle.set(new ClaimResettle(old, due));
    }
}
        if (valid != null) {
            for (Claim claim : ordered) {
                try {
                    ApplyRedate.refuse(claim, valid, settings, people, periods);
                } catch (ClaimStatusRefusedException e) {
                    continue;
                }
                RollupFigures before = rollup.figures(sheetId);
                LocalDate old = claim.getDate();
                claim.setDate(valid.date());
                claims.redate(claim);
                Person person = people.find(sheetId, claim.getPersonId());
                audit.recordOnCommit(ClaimAudit.line("CLAIM_REDATED", request.user(), person, claim, claim.getNumber())
                        + " old=" + old + " new=" + claim.getDate());
                rollup.recordChanges(sheetId, request.user(), before);
                redated++;
            }
        }
        response.send(new BulkRedateResponse(redated, selected.size() - redated));
    }
}

